+    assert_eq!(state.overlay, Some(Overlay::Help { scroll: 3 }));
+    assert_eq!(state.on_mouse(click(10, 5)), None);
+    assert_eq!(state.overlay, Some(Overlay::Help { scroll: 3 }), "a click does not close or change help");
