+    for (width, height) in [(1, 1), (2, 2), (10, 3), (20, 4), (30, 6), (40, 8), (80, 24), (200, 5)] {
+        let mut state = with_tools(5);
+        draw(&mut state, width, height);
+        for kind in every_mouse_kind() {
